class Solution { public int minimumScore(String s,String t){int n=s.length(),m=t.length();int[] suffix=new int[m+1];suffix[m]=n;int position=n-1;for(int i=m-1;i>=0;i--){while(position>=0&&s.charAt(position)!=t.charAt(i))position--;suffix[i]=position;position--;}int answer=m,right=0,prefixPosition=-1,searchPosition=0;for(int left=0;left<=m;left++){right=Math.max(right,left);while(right<=m&&suffix[right]<=prefixPosition)right++;if(right<=m)answer=Math.min(answer,right-left);if(left==m)break;while(searchPosition<n&&s.charAt(searchPosition)!=t.charAt(left))searchPosition++;if(searchPosition==n)break;prefixPosition=searchPosition++;}return answer;} }
